ll dp[17][65538][17];
char a[20];
ll b[20];
ll mo[1100005];
ll f(ll m,ll p,ll pos)
{
	if(dp[m][p][pos]!=-1)
		return dp[m][p][pos];
	if(pos==0)
	{
		if(((1<<m)&p))
			dp[m][p][pos]=1;
		else
			dp[m][p][pos]=0;
		return dp[m][p][pos];
	}
	ll j=0;
	for(ll i=0;i<=15;i++)
	{
		j+=f(max(m,i),mo[p*16+i],pos-1);
	}
	return dp[m][p][pos]=j;
}
int main()
{
